import html

def search_results_html(query: str, count: int) -> str:
    escaped_query = html.escape(query)
    html_part = f"<p>You searched for: {escaped_query}</p>"
    if count == 0:
        html_part += "<p>No results.</p>"
    else:
        html_part += f"<p>{count} results found.</p>"
    return html_part

def search_results_html(query: str, count: int) -> str:
        escaped_query = html.escape(query, quote=True)
        html_part = f"<p>You searched for: {escaped_query}</p>"
        if count == 0:
            html_part += "<p>No results.</p>"
        else:
            html_part += f"<p>{count} results found.</p>"
        return html_part

import subprocess

def echo_message(message: str) -> list:
    # Use a list to avoid shell invocation and prevent injection
    cmd = ['echo', f'Message: {message}']
    completed = subprocess.run(cmd, capture_output=True, text=True)
    return completed.stdout.splitlines()

def count_words_shell(text: str) -> int:
    import shlex
    cmd = f"echo {shlex.quote(text)} | wc -w"
    result = subprocess.check_output(cmd, shell=True, text=True)
    return int(result.strip())

import shlex

def echo_message(message: str) -> list:
    cmd = ['echo', f"Message: {message}"]
    completed = subprocess.run(cmd, capture_output=True, text=True)
    return completed.stdout.splitlines()

def count_words_shell(text: str) -> int:
    cmd = ['bash', '-c', f"echo {shlex.quote(text)} | wc -w"]
    completed = subprocess.run(cmd, capture_output=True, text=True)
    return int(completed.stdout.strip())

def count_words_shell(text: str) -> int:
    # Use a list of arguments to avoid shell injection
    result = subprocess.check_output(["echo", text, "|", "wc", "-w"], shell=False, text=True)
    return int(result.strip())
